def initial_decision_context(self, context):
    """Supply actual job inputs and acceptance, without a setup recipe."""
    if context.role not in ('launch', 'launch_hpc'):
        return {}
    from gene_annotation_episode.episodic_workflow.root.a107.method_loop.identities import EpisodeRef
    prefixes = [context.path[:i + 1] for i, part in enumerate(context.path) if part[0] == 'hpc']
    if not prefixes:
        return {}
    owner = EpisodeRef(context.run_id, prefixes[-1]).episode_id
    ledger = HPCLedger.open_existing(self.directory / 'hpc' / hpc_queue.digest([context.run_id, owner]))
    selected = plain(context.assignment)
    key = 'launch_assignment' if context.role == 'launch' else 'practical_assignment'
    plans = [row['body'] for row in ledger.records('plan') if row['body'][key] == selected]
    if len(plans) != 1 or ledger.read('owner')['scope'] != plain(context.scope):
        raise ValueError('hpc_launch_preparation_identity_conflict')
    plan = plans[0]
    from gene_annotation_episode.episodic_workflow.root.a107.practical_execution_state import _immutable
    input_directory = ledger.path.parent / 'launch-inputs'
    input_directory.mkdir(exist_ok=True)
    input_path = input_directory / (plan['plan_id'] + '.json')
    _immutable(input_path, plan)
    return {'hpc_execution_job': {'plan_id': plan['plan_id'], 'objective': ledger.commission['objective'], 'scientific_manifest': deepcopy(plan['manifest']), 'scientific_acceptance': deepcopy(ledger.commission['obligations']), 'supplied_input_file': str(input_path.resolve()), 'coordinator_workspace': str(self.directory.resolve()), 'instructions': 'The supplied local input file contains the frozen scientific manifest and reference source files. Use general terminal commands on the coordinator or assigned resource as needed; choose your scripts, environment and transfer method. Do not transcribe supplied source code into a child goal. Reference implementation files are available inputs, not a required execution procedure. Preserve original unit identities, scientific inputs, output/progress formats and acceptance predicates. Run computation in the actual allocation and retain its original identity. An uncertain submission must be investigated rather than duplicated.'}}

